// Enmascara datos sensibles antes de enviarlos a la IA
const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);

const mask = (v) => {
  if (typeof v !== 'string') return v;
  return v
    .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[EMAIL]')
    .replace(/\b\d{2}-?\d{8}-?\d\b/g, '[CUIT]')
    .replace(/\b(?:\d[ -]?){13,19}\b/g, '[TARJETA/CBU]')
    .replace(/\b\d{1,2}\.?\d{3}\.?\d{3}\b/g, '[DNI]');
};

const sensibles = /(cuit|cuil|dni|documento|email|mail|correo|telefono|tel|celular|cbu|alias|tarjeta|direccion|domicilio|clave|password|contrase|usuario|token)/i;

const limpias = rows.map((r, idx) => {
  const out = { fila: idx + 1 };
  for (const [k, v] of Object.entries(r)) {
    out[k] = sensibles.test(k) ? '[OCULTO]' : mask(v);
  }
  return out;
});

return [{ json: { total_filas: limpias.length, datos: JSON.stringify(limpias) } }];

const r = $input.first().json;
let text = '';
if (Array.isArray(r.content)) {
  text = r.content.filter(b => b && b.type === 'text').map(b => b.text).join('');
} else if (typeof r.content === 'string') {
  text = r.content;
} else if (typeof r.text === 'string') {
  text = r.text;
}
text = text.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();

let d;
try {
  d = JSON.parse(text);
} catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  try { d = m ? JSON.parse(m[0]) : null; } catch (e2) { d = null; }
}
if (!d) d = { nivel_riesgo: 'desconocido', cantidad_alertas: 0, resumen: 'No se pudo interpretar la respuesta de la IA', hallazgos: [] };

const hallazgos = Array.isArray(d.hallazgos) ? d.hallazgos : [];

// Conteo de tareas por ESTADO_GENERAL (1 = completo, 2 = en proceso, 3 = sin comenzar)
const filas = $('Leer Tabla Operativa Junior').all().map(i => i.json).filter(r => r.ID_Empresa !== undefined && r.ID_Empresa !== '');
const estado = (r) => Number(r.ESTADO_GENERAL);
const total = filas.length;
const completadas = filas.filter(r => estado(r) === 1).length;
const enProceso = filas.filter(r => estado(r) === 2).length;
const sinComenzar = filas.filter(r => estado(r) === 3).length;
const pct = total > 0 ? Math.round(((enProceso + sinComenzar) / total) * 100) / 100 : 0;

return [{ json: {
  fecha_hora: $now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd HH:mm'),
  total_empresas: total,
  tareas_completadas: completadas,
  tareas_en_proceso: enProceso,
  tareas_sin_comenzar: sinComenzar,
  pct_pendiente: pct,
  cantidad_alertas: Number(d.cantidad_alertas ?? hallazgos.length) || hallazgos.length,
  nivel_riesgo_predominante: String(d.nivel_riesgo || 'desconocido').toUpperCase(),
  resumen_claude: d.resumen || '',
} }];
